// ============================================
// VALIDATION INPUT & EXTRACTION API KEY
// ============================================

const input = $input.first().json;
const body = input.body || {};
const headers = input.headers || {};

// --- Validation des champs requis ---
if (!body.items || !Array.isArray(body.items) || body.items.length === 0) {
  return {
    error: true,
    error_code: 'MISSING_ITEMS',
    message: 'Le champ "items" est requis et doit être un tableau non vide'
  };
}

if (!body.context || typeof body.context !== 'string') {
  return {
    error: true,
    error_code: 'MISSING_CONTEXT',
    message: 'Le champ "context" est requis'
  };
}

// --- Extraction API Key depuis headers ---
// Cherche dans différents formats de headers (lowercase/mixed)
const apiKey = headers['x-openai-api-key'] 
  || headers['X-OpenAI-API-Key'] 
  || headers['X-Openai-Api-Key'];

if (!apiKey) {
  return {
    error: true,
    error_code: 'MISSING_API_KEY',
    message: 'Header X-OpenAI-API-Key requis'
  };
}

// --- Extraction Project ID ---
const projectId = headers['x-project-id'] 
  || headers['X-Project-ID'] 
  || headers['X-Project-Id']
  || 'unknown';

// --- Préparation des items ---
const items = body.items.map(item => ({
  item_name: item.item_name || item.name || '',
  category: item.category || 'ingredient'
}));

// --- Retour des données validées ---
return {
  error: false,
  data: {
    items: items,
    context: body.context,
    discord_user_id: body.discord_user_id || null,
    locale: body.locale || 'fr-FR',
    project_id: projectId,
    items_count: items.length
  },
  credentials: {
    openai_api_key: apiKey
  }
};

