      "original": "nom original de l'item",
      "refined": "nom affiné après raisonnement",
      "category": "ingredient ou ustensile",
      "reasoning": {
        "layers": {
          "lexical": "analyse de la couche 1",
          "context": "analyse de la couche 2",
          "knowledge": "analyse de la couche 3",
          "precision": "analyse de la couche 4"
        },
        "justification": "résumé court pour affichage utilisateur",
        "confidence": 0.92,
        "variants": [
          {"name": "variante possible", "reason": "pourquoi cette variante"}
        ]
      },
      "search_query": "requête optimisée pour recherche produit avec marque française"
    }
  ]
}"
    }
  ]
