// ============================================
// PARSE LLM RESPONSE & PREPARE ITEMS
// ============================================

const llmResponse = $input.first().json;
const validationData = $('Validate Input').first().json;

// --- Vérifier les erreurs OpenAI ---
if (llmResponse.error) {
  return [{
    json: {
      error: true,
      error_code: 'OPENAI_ERROR',
      message: llmResponse.error.message || 'Erreur OpenAI',
      details: llmResponse.error
    }
  }];
}

// --- Parser la réponse ---
let analysis;
try {
  const content = llmResponse.choices[0].message.content;
  const parsed = JSON.parse(content);
  analysis = parsed.analysis;

  if (!analysis || !Array.isArray(analysis)) {
    throw new Error('Missing analysis array in response');
  }
} catch (e) {
  return [{
    json: {
      error: true,
      error_code: 'PARSE_ERROR',
      message: 'Impossible de parser la réponse LLM: ' + e.message
    }
  }];
}

// --- Retourner chaque item séparément pour traitement parallèle ---
const items = analysis.map((item, index) => ({
  json: {
    index: index,
    original: item.original,
    refined: item.refined,
    category: item.category,
    reasoning: item.reasoning,
    search_query: item.search_query,
    // Passer les credentials pour les appels suivants
    _credentials: validationData.credentials,
    _context: validationData.data.context
  }
}));

return items;

// ============================================
// AGGREGATE ALL RESULTS
// ============================================

const searchResults = $input.all();
const parsedItems = $('Parse LLM Response').all();
const validationData = $('Validate Input').first().json;

const shoppingList = [];
let totalCents = 0;

for (let i = 0; i < searchResults.length; i++) {
  const searchResult = searchResults[i].json;
  const itemData = parsedItems[i].json;

  // --- Parser le produit trouvé ---
  let product = null;

  try {
    if (searchResult.choices && searchResult.choices[0]) {
      const content = searchResult.choices[0].message.content;
      const parsed = JSON.parse(content);
      product = parsed.product;
    }
  } catch (e) {
    // Produit par défaut si erreur
    product = null;
  }

  // --- Produit par défaut si non trouvé ---
  if (!product) {
    product = {
      name: `${itemData.refined} (non trouvé)`,
      description: 'Produit non disponible',
      price_cents: 0,
      price_display: '-- €',
      currency: 'EUR',
      brand: 'N/A',
      seller: 'N/A',
      url: null,
      image_url: null
    };
  }

  // --- Calcul du total ---
  if (product.price_cents && typeof product.price_cents === 'number') {
    totalCents += product.price_cents;
  }

  // --- Construire l'item de la liste ---
  shoppingList.push({
    original_item: itemData.original,
    refined_item: itemData.refined,
    category: itemData.category,
    reasoning: itemData.reasoning,
    product: product
  });
}

// --- Formater le total ---
const totalEuros = (totalCents / 100).toFixed(2).replace('.', ',');
const totalDisplay = `${totalEuros} €`;

// --- Construire la réponse finale ---
return {
  success: true,
  context: validationData.data.context,
  project_id: validationData.data.project_id,
  discord_user_id: validationData.data.discord_user_id,
  locale: validationData.data.locale,
  items_count: shoppingList.length,
  shopping_list: shoppingList,
  total_cents: totalCents,
  total_display: totalDisplay,
  metadata: {
    workflow_version: '2.0',
    reasoning_model: 'gpt-4o',
    search_model: 'gpt-4o-mini',
    timestamp: new Date().toISOString()
  }
};

